-- Chinese Ascension series merchandise and purchase gifts found in the Exchange Society screenshots. Safe to run more than once.
insert into promo_items (id, r, data)
select 'item-10806', 10806, $j${"cat": "COLLECTIBLE", "nm": "Ascension Double Art Card Sleeves - Vi & Jinx", "se": "N/A", "cn": "N/A", "ra": "N/A", "do": "N/A", "tg": "Card Sleeves\nAscension\nVi\nJinx", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/ascension-double-art-card-sleeves-vi-jinx-ch-item-10806.webp", "inf": "Double art card sleeve set (Vi and Jinx) from the Chinese Ascension series merchandise.", "r": 10806, "id": "item-10806", "la": "Chinese", "ev": "China - Ascension series merchandise", "ty": "Card Sleeves", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": ""}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10806' or (data->>'nm' = $n$Ascension Double Art Card Sleeves - Vi & Jinx$n$ and data->>'la' = 'Chinese'));
